   589  void CoapBase::ProcessReceivedRequest(Message &aMessage, const Ip6::MessageInfo &aMessageInfo)
   590  {
   591      char     uriPath[Resource::kMaxReceivedUriPath];
   592      char *   curUriPath     = uriPath;
   593      Message *cachedResponse = NULL;
   594      otError  error          = OT_ERROR_NOT_FOUND;
   595
   596      if (mInterceptor != NULL)
   597      {
   598          SuccessOrExit(error = mInterceptor(aMessage, aMessageInfo, mContext));
   599      }
   600
   601      switch (mResponsesQueue.GetMatchedResponseCopy(aMessage, aMessageInfo, &cachedResponse))
   602      {
   603      case OT_ERROR_NONE:
   604          error = Send(*cachedResponse, aMessageInfo);
   605          // fall through
   606          ;
   607
   608      case OT_ERROR_NO_BUFS:
   609          ExitNow();
   610
   611      case OT_ERROR_NOT_FOUND:
   612      default:
   613          break;
   614      }
   615
   616      for (const otCoapOption *option = aMessage.GetFirstOption(); option != NULL; option = aMessage.GetNextOption())
   617      {
   618          switch (option->mNumber)
   619          {
   620          case OT_COAP_OPTION_URI_PATH:
   621              if (curUriPath != uriPath)
   622              {
   623                  *curUriPath++ = '/';
   624              }
   625
   626              VerifyOrExit(option->mLength < sizeof(uriPath) - static_cast<size_t>(curUriPath + 1 - uriPath));
   627
   628              aMessage.GetOptionValue(curUriPath);
   629              curUriPath += option->mLength;
   630              break;
   631
   632          default:
   633              break;
   634          }
   635      }
   636
   637      curUriPath[0] = '\0';
   638
   639      for (const Resource *resource = mResources; resource; resource = resource->GetNext())
   640      {
   641          if (strcmp(resource->mUriPath, uriPath) == 0)
   642          {
   643              resource->HandleRequest(aMessage, aMessageInfo);
   644              error = OT_ERROR_NONE;
   645              ExitNow();
   646          }
   647      }
   648
   649      if (mDefaultHandler)
   650      {
   651          mDefaultHandler(mDefaultHandlerContext, &aMessage, &aMessageInfo);
   652          error = OT_ERROR_NONE;
   653      }
   654
   655  exit:
   656
   657      if (error != OT_ERROR_NONE)
   658      {
   659          otLogInfoCoapErr(error, "Failed to process request");
   660
   661          if (error == OT_ERROR_NOT_FOUND && !aMessageInfo.GetSockAddr().IsMulticast())
   662          {
   663              SendNotFound(aMessage, aMessageInfo);
   664          }
